pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up caller with ether
        address user = address(0x1234);
        vm.deal(user, 2 ether);

        // First call: Put with unlock time far in future
        vm.prank(user);
        c.Put{value: 1 ether}(block.timestamp + 1000);

        // Now warp time past unlock time to satisfy time condition
        vm.warp(block.timestamp + 2000);

        // Try to collect 1 ether - should succeed in reference, fail in bug
        bool ok;
        try c.Collect(1 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, check the balance: reference allows collect, so balance is 0
        // Buggy contract reverts, so balance remains 1 ether
        bool balanceIsZero = (c.Acc(user).balance == 0);
        assertTrue(balanceIsZero);
    }
}

