        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Put{value: 1 ether}(block.timestamp); // unlock time = current timestamp
        // Now block.timestamp equals unlock time. Attempt Collect(0.5 ether)
        bool ok;
        vm.prank(alice);
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }
        // Reference (strict >) should revert because timestamp == unlockTime, so ok false; buggy (>=) should succeed, ok true
        assertTrue(!ok);
    }
}

