pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: fund caller with 2 ether, set block.timestamp to 10
        vm.deal(address(this), 2 ether);
        vm.warp(10);
        // Put 1 ether with unlockTime = 10 (same as block.timestamp)
        c.Put{value: 1 ether}(10);

        // Attempt Collect for 0.5 ether
        bool ok;
        try c.Collect(0.5 ether) { ok = true; } catch { ok = false; }

        // Reference (>): block.timestamp (10) > unlockTime (10) is false -> revert -> ok = false
        // Buggy (>=): block.timestamp (10) >= unlockTime (10) is true -> success -> ok = true
        assertTrue(!ok, "Reference allows at exact unlock time, but it should not");
    }
